import{_ as n,o as t,c as r,ae as i}from"./chunks/framework.Cqu5Y2mC.js";const m=JSON.parse('{"title":"Projekt „CitBin“ – Intelligente Müllstandserfassung für die Stadt Singen","description":"","frontmatter":{},"headers":[],"relativePath":"00-Organisation/01-Projektbeschreibung/index.md","filePath":"00-Organisation/01-Projektbeschreibung/index.md"}'),a={name:"00-Organisation/01-Projektbeschreibung/index.md"};function s(l,e,o,d,g,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="projekt-„citbin-–-intelligente-mullstandserfassung-fur-die-stadt-singen" tabindex="-1">Projekt „CitBin“ – Intelligente Müllstandserfassung für die Stadt Singen <a class="header-anchor" href="#projekt-„citbin-–-intelligente-mullstandserfassung-fur-die-stadt-singen" aria-label="Permalink to &quot;Projekt „CitBin“ – Intelligente Müllstandserfassung für die Stadt Singen&quot;">​</a></h1><p>Die Klasse <strong>TG 12/3 des Technischen Gymnasiums</strong> mit <strong>13 Lernenden</strong> führt im Schuljahr <strong>2025/2026</strong> ein praxisorientiertes Projekt durch. Ziel ist die Weiterentwicklung eines Systems zur <strong>Sensorerfassung und Darstellung der Füllstände von Mülleimern</strong> in der <strong>Stadt Singen</strong>.</p><p>Das Projekt ist als <strong>realitätsnahes Unternehmensprojekt</strong> organisiert: Die Schülerinnen und Schüler arbeiten in Teams, übernehmen unterschiedliche Rollen innerhalb der Organisation und setzen gemeinsam eine technische Lösung um. Am Ende des Projekts wird <strong>die Leistung jedes einzelnen Lernenden individuell bewertet</strong>.</p><p>Das Projekt baut auf einem <strong>Pilotprojekt der damaligen Klasse TG 12/3 aus dem Schuljahr 2024/2025</strong> auf, das von <strong>März bis Juli 2025</strong> durchgeführt wurde. Die aktuelle Projektgruppe entwickelt dieses System weiter und bringt es in eine <strong>erste produktive Pilotphase</strong>.</p><p>Die Schülerinnen und Schüler sammeln dabei <strong>praktische Erfahrungen in Projektmanagement, Softwareentwicklung, Hardwareintegration und Teamarbeit</strong> – unter realen Bedingungen mit einem echten Auftraggeber.</p><h1 id="personen-und-rollen" tabindex="-1">Personen und Rollen <a class="header-anchor" href="#personen-und-rollen" aria-label="Permalink to &quot;Personen und Rollen&quot;">​</a></h1><p>siehe <a href="./01a-Personen+Rollen.html">Personen und Rollen</a></p><h1 id="projektzeitraum" tabindex="-1">Projektzeitraum <a class="header-anchor" href="#projektzeitraum" aria-label="Permalink to &quot;Projektzeitraum&quot;">​</a></h1><p><strong>März bis Juli 2026</strong></p><p>Die regelmäßigen Projekttreffen finden <strong>freitags von 7:55 bis 11:10 Uhr</strong> statt.</p><p>Ziel ist es, das System <strong>bis Anfang Juli</strong> fertigzustellen und an die <strong>Stadt Singen zu übergeben</strong>.</p><p>siehe <a href="./01a-Zeitplanung.html">Zeitplanung</a></p><h1 id="projektziel" tabindex="-1">Projektziel <a class="header-anchor" href="#projektziel" aria-label="Permalink to &quot;Projektziel&quot;">​</a></h1><p>Das Projekt beschäftigt sich mit der <strong>digitalen Erfassung und Darstellung von Füllständen öffentlicher Mülleimer</strong>.</p><p>Zentrale Bestandteile des Systems sind:</p><ul><li>Sensoren in Mülleimern zur <strong>Messung des Füllstands</strong></li><li><strong>Funkübertragung über die Technologie mioty</strong></li><li>eine <strong>Applikation</strong>, die den aktuellen Füllstand der Mülleimer anzeigt</li><li><strong>Serverinfrastruktur</strong>, auf der die Daten verarbeitet und dargestellt werden</li></ul><p>Im Rahmen einer <strong>Pilotphase</strong> werden zunächst <strong>fünf Mülleimer</strong> mit Sensoren ausgestattet.</p><p>Die entwickelte Software wird anschließend:</p><ul><li>auf <strong>Servern der Stadt Singen</strong> betrieben</li><li>an die <strong>Stadtverwaltung übergeben</strong></li></ul><h1 id="projektvorgehen" tabindex="-1">Projektvorgehen <a class="header-anchor" href="#projektvorgehen" aria-label="Permalink to &quot;Projektvorgehen&quot;">​</a></h1><p>Das Projekt wird nach Prinzipien des <strong>agilen Projektmanagements (SCRUM)</strong> organisiert.</p><p>Zu Beginn werden innerhalb des Projektteams <strong>Unternehmensrollen und Verantwortlichkeiten festgelegt</strong>.</p><p>Wichtige Schritte im Projekt:</p><ul><li>Besetzung der Positionen innerhalb der Projektorganisation</li><li>Erstgespräch mit dem Kunden (Stadt Singen)</li><li>Erstellung eines <strong>Lastenhefts</strong> mit den Anforderungen</li><li>Klärung des <strong>zeitlichen Rahmens</strong></li><li>Klärung des <strong>finanziellen Rahmens</strong></li><li>Umsetzung der technischen Lösung in <strong>agilen Entwicklungszyklen</strong></li></ul><h1 id="projektinhalt" tabindex="-1">Projektinhalt <a class="header-anchor" href="#projektinhalt" aria-label="Permalink to &quot;Projektinhalt&quot;">​</a></h1><p>Im Projekt werden sowohl <strong>technische als auch organisatorische Aufgaben</strong> umgesetzt.</p><p>Dazu gehören unter anderem:</p><ul><li>Auswahl der <strong>Mülleimerstandorte</strong>, die in das System eingebunden werden</li><li>Installation neuer <strong>Sensoren, Basisstationen und Antennen</strong></li><li>Weiterentwicklung des <strong>bestehenden Systems aus dem Pilotprojekt</strong></li><li>Anbindung <strong>neuer Sensoren und eines neuen Servers</strong> für die Sensordaten</li><li>Integration der Daten in die <strong>bestehende Applikation</strong></li></ul><h1 id="bewertung-der-schulerleistungen" tabindex="-1">Bewertung der Schülerleistungen <a class="header-anchor" href="#bewertung-der-schulerleistungen" aria-label="Permalink to &quot;Bewertung der Schülerleistungen&quot;">​</a></h1><p>Am Ende des Projekts wird <strong>jede Schülerin und jeder Schüler individuell bewertet</strong>.</p><p>Grundlage der Bewertung sind mehrere Kriterien:</p><h2 id="dokumentation" tabindex="-1">Dokumentation <a class="header-anchor" href="#dokumentation" aria-label="Permalink to &quot;Dokumentation&quot;">​</a></h2><ul><li>Jede Person dokumentiert ihre Aufgaben und Tätigkeiten</li><li>Führung eines <strong>Berichtshefts</strong> mit Zuordnung, wer welche Aufgabe hatte</li></ul><h2 id="personale-kompetenz" tabindex="-1">Personale Kompetenz <a class="header-anchor" href="#personale-kompetenz" aria-label="Permalink to &quot;Personale Kompetenz&quot;">​</a></h2><ul><li><strong>Termintreue</strong></li><li><strong>Zuverlässigkeit</strong></li></ul><h2 id="teamarbeit" tabindex="-1">Teamarbeit <a class="header-anchor" href="#teamarbeit" aria-label="Permalink to &quot;Teamarbeit&quot;">​</a></h2><ul><li>Kommunikation im Team</li><li>Zusammenarbeit</li><li>Zuverlässigkeit bei gemeinsamen Aufgaben</li></ul><h2 id="feedbackgesprache" tabindex="-1">Feedbackgespräche <a class="header-anchor" href="#feedbackgesprache" aria-label="Permalink to &quot;Feedbackgespräche&quot;">​</a></h2><p>Im Verlauf des Projekts finden <strong>zwei Feedbacktage</strong> statt, an denen der Projektstand sowie die individuelle Mitarbeit reflektiert werden.</p><h2 id="teamleistung" tabindex="-1">Teamleistung <a class="header-anchor" href="#teamleistung" aria-label="Permalink to &quot;Teamleistung&quot;">​</a></h2><p>Das Team erhält eine Gesamtbewertung. Diese wird innerhalb der Teammitglieder in einem vorgegeben Rahmen so verteilt, dass der Mittelwert der Teambewertung entspricht.</p>',41)])])}const c=n(a,[["render",s]]);export{m as __pageData,c as default};
